widget.solution:
from math import comb

def tail(k, n, p):
    """Chance of k or more in n independent trials."""
    return sum(comb(n, j) * p**j * (1 - p)**(n - j)
               for j in range(k, n + 1))

def book_tail(k, n, q, p_bad, p_good):
    """Chance of k or more defaults among n loans."""
    return q * tail(k, n, p_bad) + (1 - q) * tail(k, n, p_good)
